3	import org.springframework.beans.factory.annotation.Autowired;
4	import org.springframework.context.annotation.Bean;
5	import org.springframework.context.annotation.Configuration;
6	import org.springframework.security.authentication.AuthenticationManager;
7	import org.springframework.security.config.annotation.authentication.configuration.AuthenticationConfiguration;
8	import org.springframework.security.config.annotation.web.builders.HttpSecurity;
9	import org.springframework.security.config.annotation.web.configuration.EnableWebSecurity;
10	import org.springframework.security.config.http.SessionCreationPolicy;
11	import org.springframework.security.crypto.bcrypt.BCryptPasswordEncoder;
12	import org.springframework.security.crypto.password.PasswordEncoder;
13	import org.springframework.security.web.SecurityFilterChain;
14	import org.springframework.security.web.authentication.UsernamePasswordAuthenticationFilter;
15	import org.springframework.web.cors.CorsConfiguration;
16	import org.springframework.web.cors.CorsConfigurationSource;
17	import org.springframework.web.cors.UrlBasedCorsConfigurationSource;
18	
19	import java.util.Arrays;
20	
21	@Configuration
22	@EnableWebSecurity
23	public class SecurityConfig {
24	
25		@Autowired
26		private JwtUtil jwtUtil;
27	
28		@Autowired
29		private CustomUserDetailsService userDetailsService;
30	
31		@Bean
32		public SecurityFilterChain filterChain(HttpSecurity http) throws Exception {
33			http.cors(cors -> cors.configurationSource(corsConfigurationSource()))
34				.csrf(csrf -> csrf.disable())
35				.sessionManagement(session -> session.sessionCreationPolicy(SessionCreationPolicy.STATELESS))
36				.authorizeHttpRequests(authz -> authz.requestMatchers("/api/auth/**")
37					.permitAll()
38					.requestMatchers("/swagger-ui/**")
39					.permitAll()
40					.requestMatchers("/v3/api-docs/**")
41					.permitAll()
42					.requestMatchers("/swagger-resources/**")
43					.permitAll()
44					.requestMatchers("/webjars/**")
45					.permitAll()
46					.requestMatchers("/actuator/**")
47					.permitAll()
48					.requestMatchers("/api/**")
49					.authenticated()
50					.anyRequest()
51					.permitAll())
52				.addFilterBefore(new JwtAuthenticationFilter(jwtUtil, userDetailsService),
53						UsernamePasswordAuthenticationFilter.class);
54	
55			return http.build();
56		}
57	
58		@Bean
59		public PasswordEncoder passwordEncoder() {
60			return new BCryptPasswordEncoder();
61		}
62	
63		@Bean
64		public AuthenticationManager authenticationManager(AuthenticationConfiguration config) throws Exception {
65			return config.getAuthenticationManager();
66		}
67	
68		@Bean
69		public CorsConfigurationSource corsConfigurationSource() {
70			CorsConfiguration configuration = new CorsConfiguration();
71			configuration.setAllowedOriginPatterns(Arrays.asList("*"));
72			configuration.setAllowedMethods(Arrays.asList("GET", "POST", "PUT", "DELETE", "OPTIONS"));
73			configuration.setAllowedHeaders(Arrays.asList("*"));
74			configuration.setAllowCredentials(true);
75	
76			UrlBasedCorsConfigurationSource source = new UrlBasedCorsConfigurationSource();
77			source.registerCorsConfiguration("/**", configuration);
78			return source;
79		}
80	
81	}
