    if "equalTo" in a:
        return f'                    .body("{path}", equalTo("{esc_java(a["equalTo"])}"))'
    if "containsString" in a:
        return f'                    .body("{path}", containsString("{esc_java(a["containsString"])}"))'
    if a.get("notNullValue"):
