package org.springframework.samples.petclinic.blackbox;

import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.BASE_URL;
import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.executeSqlTemplate;
import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.testId;
import static org.springframework.samples.petclinic.blackbox.support.BlackBoxSupport.testSeq;
import static io.restassured.RestAssured.given;
import static org.hamcrest.Matchers.equalTo;

import java.util.Map;

import org.junit.jupiter.api.Test;
import org.junit.jupiter.api.TestInfo;
import org.junit.jupiter.api.TestInstance;
import org.junit.jupiter.api.parallel.Execution;
import org.junit.jupiter.api.parallel.ExecutionMode;

import io.restassured.http.ContentType;

/**
 * Black-Box API Integration Test (template-rendered v2)
 *
 * @target-controller OwnerRestController (src/main/java/org/springframework/samples/petclinic/owner/OwnerRestController.java)
 * @target-api GET /api/owners/{ownerId}
 *
 * OwnerRestController.getOwner: ownerRepository.findById(ownerId) -> 200 Owner JSON (with nested pets/types/visits) or 404 empty body.
 * Auth: SecurityConfig requires Authorization: Bearer <jwt> on /api/** (JwtAuthenticationFilter). Token obtained via POST /api/auth/login (hardcoded admin/password in CustomUserDetailsService, no DB dependency).
 * No external HTTP dependencies (detect-external-calls: 0 external_calls). No WireMock stub needed.
 * ownerId is a required @PathVariable Integer with no @Valid constraints; RED (DB_WHERE) per extract-key-params. VTC NULL/EMPTY standard rules do not map cleanly onto a required single path segment (they would change routing, not trigger a validation branch) so they are represented as ATC_ownerId_emptySegment (404, route mismatch) instead of a literal NULL/EMPTY value.
 * Dynamic IDs (SEQ-based) cannot be literal-asserted in response body (template renderer only supports static expectBody values), so response 'id' fields are intentionally not asserted; all other literal fixture fields are asserted with exact equalTo/equalToInt.
 */
@TestInstance(TestInstance.Lifecycle.PER_METHOD)
@Execution(ExecutionMode.CONCURRENT)
class OwnerGetByIdBlackBoxTest {

    private Map<String, String> seed(TestInfo info) {
        long seq = testSeq(info);
        return Map.of(
                "SEQ", Long.toString(seq),
                "PET1_SEQ", Long.toString(seq + 1),
                "PET2_SEQ", Long.toString(seq + 2),
                "VISIT_SEQ", Long.toString(seq + 3));
    }

    private void arrange(Map<String, String> p) {
        executeSqlTemplate("sql/owners-get-by-id-teardown.sql", p);
        executeSqlTemplate("sql/owners-get-by-id-setup.sql", p);
    }

    private String authenticate(Map<String, String> p) {
        return given().baseUri(BASE_URL)
                .contentType(ContentType.JSON)
                .body("{\"username\": \"admin\", \"password\": \"password\"}")
        .when().post("/api/auth/login")
        .then().statusCode(200)
        .extract().jsonPath().getString("token");
    }

    @Test
    void NTC_getOwner_success_ownerFields(TestInfo info) {
        // NTC 1/3 (test-plan NTC_branch_getOwner_2 - happy path): top-level Owner fields match fixture exactly
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", p.get("SEQ"))
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(200)
                    .body("firstName", equalTo("QaOwnerFNXXXXXXXXXXXXXXXXXXXXX"))
                    .body("lastName", equalTo("QaOwnerLNXXXXXXXXXXXXXXXXXXXXX"))
                    .body("address", equalTo("123 Max Length Blvd Apt ZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZZ"))
                    .body("city", equalTo("MaxLenCityYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYYY"))
                    .body("telephone", equalTo("6085551234"));
        } finally {
            executeSqlTemplate("sql/owners-get-by-id-teardown.sql", p);
        }
    }

    @Test
    void NTC_getOwner_success_petsList(TestInfo info) {
        // NTC 2/3: nested pets[] ordered by name (JPA @OrderBy("name")) - Ares before Buddy
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", p.get("SEQ"))
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(200)
                    .body("pets.size()", equalTo(2))
                    .body("pets[0].name", equalTo("Ares"))
                    .body("pets[0].type.name", equalTo("dog"))
                    .body("pets[0].birthDate", equalTo("2018-07-15"))
                    .body("pets[1].name", equalTo("Buddy"))
                    .body("pets[1].type.name", equalTo("cat"))
                    .body("pets[1].birthDate", equalTo("2015-05-01"));
        } finally {
            executeSqlTemplate("sql/owners-get-by-id-teardown.sql", p);
        }
    }

    @Test
    void NTC_getOwner_success_visitsNested(TestInfo info) {
        // NTC 3/3: nested pets[].visits[] - only Buddy (pets[1]) has a visit, Ares (pets[0]) has none
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", p.get("SEQ"))
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(200)
                    .body("pets[0].visits.size()", equalTo(0))
                    .body("pets[1].visits.size()", equalTo(1))
                    .body("pets[1].visits[0].description", equalTo("Annual checkup"))
                    .body("pets[1].visits[0].date", equalTo("2023-01-10"));
        } finally {
            executeSqlTemplate("sql/owners-get-by-id-teardown.sql", p);
        }
    }

    @Test
    void VTC_ownerId_INVALID_FORMAT(TestInfo info) {
        // RED param ownerId, VTC standard rule INVALID_FORMAT: non-numeric path segment fails @PathVariable Integer conversion -> Spring Boot default 400
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", "NOT_A_NUMBER")
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/owners-get-by-id-teardown.sql", p);
        }
    }

    @Test
    void VTC_ownerId_SPECIAL_CHAR(TestInfo info) {
        // RED param ownerId, VTC standard rule SPECIAL_CHAR (DB_WHERE): SQL-injection-shaped value never reaches the query because Integer path-variable conversion rejects it first -> 400
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", "1'; DROP TABLE owners;--")
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/owners-get-by-id-teardown.sql", p);
        }
    }

    @Test
    void VTC_ownerId_WHITE_SPACE(TestInfo info) {
        // RED param ownerId, VTC standard rule WHITE_SPACE (DB_WHERE): single-space path segment fails Integer conversion -> 400
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", " ")
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(400);;
        } finally {
            executeSqlTemplate("sql/owners-get-by-id-teardown.sql", p);
        }
    }

    @Test
    void ATC_ownerId_noData(TestInfo info) {
        // test-plan ATC_ownerId_noData: valid Integer format, no matching row (fixed id well outside the seeded SEQ range) -> controller returns ResponseEntity.notFound().build()
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", "123456789")
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(404);;
        } finally {
            executeSqlTemplate("sql/owners-get-by-id-teardown.sql", p);
        }
    }

    @Test
    void ATC_ownerId_negativeNoData(TestInfo info) {
        // Valid negative Integer format (never assigned by AUTO_INCREMENT), no matching row -> 404
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", "-1")
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(404);;
        } finally {
            executeSqlTemplate("sql/owners-get-by-id-teardown.sql", p);
        }
    }

    @Test
    void ATC_ownerId_emptySegment(TestInfo info) {
        // Empty path segment (GET /api/owners/) does not match /api/owners/{ownerId} (PathPatternParser requires a non-empty variable) nor the bare /api/owners GET mapping (trailing slash) -> 404
        Map<String, String> p = seed(info);
        arrange(p);
        String token = authenticate(p);
        try {
            given().baseUri(BASE_URL)
                    .header("Authorization", "Bearer " + token)
                    .pathParam("ownerId", "")
            .when()
                    .get("/api/owners/{ownerId}")
            .then()
                    .statusCode(404);;
        } finally {
            executeSqlTemplate("sql/owners-get-by-id-teardown.sql", p);
        }
    }
}

